	/** 
	 * jumpstart the process by instantiating2 Payment
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		paymentId = PaymentService.getPaymentInstance()
		.createPayment( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		PaymentService.getPaymentInstance()
				.createPayment( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.paymentSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Payment : " + successValue.getPaymentId());
							  if (successValue.getPaymentId().equals(paymentId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfPaymentList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Payment test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on payment consumed")
					);
			subscriber.paymentSubscribe( paymentId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Payment : " + successValue.getPaymentId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfPaymentList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on payment for paymentId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Payment. 
	 */
	protected Payment read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Payment" );

		Payment entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Payment with primary key" );
		msg.append( paymentId );
		
		PaymentFetchOneSummary fetchOneSummary = new PaymentFetchOneSummary( paymentId );

		try {
			entity = PaymentService.getPaymentInstance().getPayment( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Payment " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Payment.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Payment." );

		StringBuilder msg = new StringBuilder( "Failed to update a Payment : " );        
		Payment entity = read();
		UpdatePaymentCommand command = generateUpdateCommand();
		command.setPaymentId(entity.getPaymentId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Payment." );

			// for use later on...
			paymentId = entity.getPaymentId();

			PaymentService proxy = PaymentService.getPaymentInstance();  

			proxy.updatePayment( command ).get();

			LOGGER.info( "-- Successfully saved Payment - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + paymentId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Payment.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Payment." );

		Payment entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Payment with id " + paymentId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Payment with id " + paymentId );

			throw e;
		}

		try{
			PaymentService.getPaymentInstance().delete( new DeletePaymentCommand( entity.getPaymentId() ) ).get();
			LOGGER.info( "-- Successfully deleted Payment with id " + paymentId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Payment with id " + paymentId );

			throw e;
		}
	}

	/**
	 * get all Payments.
	 */
	protected List<Payment> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Payments:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Payment : " );        
		List<Payment> collection  = new ArrayList<>();

		try {
			// call the static get method on the PaymentService
			collection = PaymentService.getPaymentInstance().getAllPayment();
			assertNotNull( collection, "An Empty collection of Payment was incorrectly returned.");
			
			// Now print out the values
			Payment entity = null;            
			Iterator<Payment> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getPaymentId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

